@using sv_499a428ea69643358600a2b0455972a6
@using sv_499a428ea69643358600a2b0455972a6.Components.Board
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardSummaryBar Tasks="allTasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="row">
        @for (var i = 0; i < columns.Length; i++)
        {
            var col = columns[i];
            var columnTasks = FilteredTasks.Where(t => t.Status == col.Status).ToList();

            <KanbanColumn ColumnName="@col.Name"
                          Status="@col.Status"
                          Tasks="columnTasks"
                          IsFirst="(i == 0)"
                          IsLast="(i == columns.Length - 1)"
                          OnMoveLeft="HandleMoveLeft"
                          OnMoveRight="HandleMoveRight"
                          OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

@code {
    [Inject] private ITaskService TaskService { get; set; } = default!;

    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    private readonly record struct ColumnDef(string Name, string Status);

    private static readonly ColumnDef[] columns =
    [
        new("To Do", "To Do"),
        new("In Progress", "In Progress"),
        new("Done", "Done")
    ];

    private IEnumerable<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(searchText)
            ? allTasks
            : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task HandleMoveLeft(TaskItem task)
    {
        var currentIndex = Array.FindIndex(columns, c => c.Status == task.Status);
        if (currentIndex <= 0) return;

        var newStatus = columns[currentIndex - 1].Status;
        await MoveTask(task, newStatus);
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        var currentIndex = Array.FindIndex(columns, c => c.Status == task.Status);
        if (currentIndex < 0 || currentIndex >= columns.Length - 1) return;

        var newStatus = columns[currentIndex + 1].Status;
        await MoveTask(task, newStatus);
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        allTasks.Add(task);
    }
}
"}

